/**
 * Safeguard for requirement `types-shared-import-path`:
 * `import('echarts/types/dist/shared')` in users' .d.ts must resolve to
 * `echarts/types/dist/shared.d.ts` again (broken since v5.5.0 by the
 * `exports` field). Fixed upstream in 5.5.1 by adding explicit
 * `./types/dist/*` entries to `exports` in package.json.
 *
 * Run with: node agent_tests/types-shared-import-path.test.js
 */
const assert = require('assert');
const path = require('path');

const pkg = require(path.join(__dirname, '..', 'package.json'));

const names = [
    'charts',
    'components',
    'core',
    'echarts',
    'features',
    'option',
    'renderers',
    'shared'
];

assert(pkg.exports, 'package.json must have an "exports" field');

for (const name of names) {
    const key = './types/dist/' + name;
    assert.strictEqual(
        pkg.exports[key],
        './types/dist/' + name + '.d.ts',
        `exports["${key}"] must map to the corresponding .d.ts file`
    );
}

// The explicit entries must come before the catch-all "./*" so they take
// precedence for the exact subpaths.
const keys = Object.keys(pkg.exports);
assert(
    keys.indexOf('./types/dist/shared') < keys.indexOf('./*'),
    '"./types/dist/*" entries must appear before the "./*" catch-all'
);

console.log('types-shared-import-path: all package.json export entries OK');
